import * as THREE from 'three';
import type { PlayerRole } from '../core/types';
import type {
  NetMessage,
  NetStatus,
  NetTransport,
  NetTransportEvents,
  PeerPose,
  PoseArray,
} from './types';
import type { PlayerRig } from '../core/PlayerRig';
import type { XRInput } from '../core/XRInput';
import { clampAppearance, DEFAULT_APPEARANCE, type Appearance } from '../core/appearance';

export interface Peer {
  id: string;
  role: PlayerRole;
  name: string;
  /** Wie dieser Spieler aussieht — Hut, Kopf, Körper (`core/appearance.ts`). */
  look: Appearance;
  world: string;
  pose: PeerPose | null;
  lastSeen: number;
  /**
   * Die Standzeit, die dieser Spieler zuletzt angesagt hat, und wann sie hier
   * ankam — beides nach der **eigenen** Uhr. `seniorityOf` rechnet daraus die
   * aktuelle: Sie wächst überall gleich schnell weiter, also genügt eine
   * Ansage. Angesagt wird sie in `hello` und beim Weltwechsel.
   */
  since: number;
  sinceAt: number;
}

type PeerListener = (peer: Peer) => void;
/** Eine hereingekommene Chat-Zeile, roh — geputzt wird sie im `ChatLog`. */
type ChatListener = (message: ChatIn, from: string) => void;

/** Was von einer Chat-Nachricht ankommt. Alle Felder sind fremder Text. */
export interface ChatIn {
  name: string;
  text: string;
  kind: 'text' | 'code';
  note?: string;
}
type StatusListener = (status: NetStatus, detail: string) => void;
type ChangeListener = () => void;

/**
 * A WebRTC data channel copes with this easily and it is what makes
 * first-person spectating watchable.
 */
const POSE_INTERVAL = 1 / 20;
/** Only a fallback: transports that know about links report leaving directly. */
const PEER_TIMEOUT = 8;

const _mat = new THREE.Matrix4();
const _pos = new THREE.Vector3();
const _quat = new THREE.Quaternion();
const _scale = new THREE.Vector3();

/**
 * Presence and pose sync. Deliberately transport agnostic so that asymmetric
 * sessions (a VR player plus phone players) only need a different transport.
 */
export class NetSession {
  /** Replaced by the transport's own id once connected, so both agree. */
  localId = `p-${Math.random().toString(36).slice(2, 8)}`;
  readonly peers = new Map<string, Peer>();

  role: PlayerRole = 'desktop';
  name = 'Spieler';
  /**
   * Das eigene Aussehen, so wie es angesagt wird (`core/appearance.ts`).
   *
   * Es steht hier und nicht in der Pose: Ein Aussehen ändert sich einmal am
   * Abend, eine Pose zwanzigmal in der Sekunde. Wer es ändert, sagt sich neu
   * an (`announce`) — das ist eine Nachricht und kein Strom.
   */
  look: Appearance = { ...DEFAULT_APPEARANCE };
  world = 'hub';
  connected = false;
  room = '';
  /**
   * Seit wann man in der aktuellen Welt steht — als Zeitpunkt der eigenen Uhr,
   * aus dem `localSeniority` eine **Dauer** macht. Nur die geht über das Netz.
   */
  private worldSince = now();
  /** Cleared while the local camera is glued to someone else's head. */
  visible = true;
  status: NetStatus = 'offline';
  statusDetail = '';

  private transport: NetTransport | null = null;
  private poseTimer = 0;
  private joinListeners: PeerListener[] = [];
  private leaveListeners: PeerListener[] = [];
  private changeListeners: ChangeListener[] = [];
  private statusListeners: StatusListener[] = [];
  private channelListeners = new Map<string, Array<(data: unknown, from: string) => void>>();
  private chatListeners: ChatListener[] = [];
  /** Wer auf die Ströme der Mitspieler wartet — überlebt einen Transportwechsel. */
  private streamListeners: Array<(stream: MediaStream, peerId: string) => void> = [];

  get transportKind(): string {
    return this.transport?.kind ?? 'none';
  }

  /** Wie lange man selbst schon in dieser Welt steht, in Sekunden. */
  get localSeniority(): number {
    return now() - this.worldSince;
  }

  /**
   * Dasselbe für einen Mitspieler: seine letzte Ansage plus die Zeit, die
   * seither hier vergangen ist. Standzeiten wachsen überall gleich schnell, und
   * genau deshalb reicht eine Ansage statt eines Tickens über die Leitung.
   */
  seniorityOf(peer: Peer): number {
    return peer.since + (now() - peer.sinceAt);
  }

  async connect(transport: NetTransport, room = 'lobby'): Promise<void> {
    this.disconnect();
    this.transport = transport;
    this.room = room;
    this.setStatus('connecting', 'Verbinde …');

    const events: NetTransportEvents = {
      message: (message) => this.receive(message),
      peerUp: () => this.announce(),
      peerDown: (id) => this.dropPeer(id),
      status: (status, detail) => this.setStatus(status, detail ?? ''),
    };

    try {
      await transport.connect(room, events);
    } catch (error) {
      this.transport = null;
      this.setStatus('error', (error as Error).message);
      throw error;
    }

    for (const listener of this.streamListeners) transport.onPeerStream?.(listener);

    if (transport.id) this.localId = transport.id;
    this.connected = true;
    this.announce();
  }

  disconnect(): void {
    if (!this.transport) return;
    this.send({ type: 'bye', from: this.localId });
    this.transport.close();
    this.transport = null;
    this.connected = false;
    this.room = '';
    for (const id of [...this.peers.keys()]) this.dropPeer(id);
    this.setStatus('offline', '');
  }

  /** Tells everyone who and where we are. Cheap, so call it whenever it changes. */
  announce(): void {
    if (!this.connected) return;
    this.send({
      type: 'hello',
      from: this.localId,
      role: this.role,
      name: this.name,
      world: this.world,
      since: this.localSeniority,
      hat: this.look.hat,
      head: this.look.head,
      body: this.look.body,
      figure: this.look.figure,
      face: this.look.face,
    });
  }

  onPeerJoin(listener: PeerListener): void {
    this.joinListeners.push(listener);
  }

  onPeerLeave(listener: PeerListener): void {
    this.leaveListeners.push(listener);
  }

  /** Fires whenever the peer list or one of its entries changed. */
  onPeersChanged(listener: ChangeListener): void {
    this.changeListeners.push(listener);
  }

  onStatus(listener: StatusListener): void {
    this.statusListeners.push(listener);
  }

  /**
   * Schickt eine Zeile an alle im Raum.
   *
   * Allein im Raum geht nichts hinaus, und das ist keine Fehlbedienung: der
   * Verlauf ist trotzdem einer, man schreibt sich dann eben selbst etwas auf.
   * Deshalb sagt der Rückgabewert, ob wirklich jemand mithört.
   */
  sendChat(text: string, options: { kind?: 'text' | 'code'; note?: string } = {}): boolean {
    if (!this.connected) return false;
    const message: NetMessage = {
      type: 'chat',
      from: this.localId,
      name: this.name,
      text,
      kind: options.kind ?? 'text',
    };
    if (options.note) message.note = options.note;
    this.send(message);
    return this.peers.size > 0;
  }

  /** @returns das Abmelden — Welten kommen und gehen, die Sitzung bleibt. */
  onChat(listener: ChatListener): () => void {
    this.chatListeners.push(listener);
    return () => {
      this.chatListeners = this.chatListeners.filter((other) => other !== listener);
    };
  }

  /** Subscribe to a world-specific message channel. */
  on(channel: string, listener: (data: unknown, from: string) => void): void {
    const list = this.channelListeners.get(channel) ?? [];
    list.push(listener);
    this.channelListeners.set(channel, list);
  }

  off(channel: string): void {
    this.channelListeners.delete(channel);
  }

  /** Broadcast a world-specific message. */
  emit(channel: string, data: unknown): void {
    this.send({ type: 'event', from: this.localId, channel, data });
  }

  // --- Ton --------------------------------------------------------------

  /** Ob dieser Transport überhaupt Ton tragen kann (`net/Voice.ts`). */
  get canStream(): boolean {
    // Nach dem Namen gefragt und nicht nach der Methode: eine Methode aus
    // ihrem Objekt zu lösen ist genau das, wovor der Linter hier warnt.
    return this.transport !== null && 'addStream' in this.transport;
  }

  /** Das eigene Mikrofon an alle im Raum. */
  addStream(stream: MediaStream): void {
    this.transport?.addStream?.(stream);
  }

  removeStream(stream: MediaStream): void {
    this.transport?.removeStream?.(stream);
  }

  /**
   * Der Strom eines Mitspielers.
   *
   * Angemeldet wird beim Transport, und der wechselt beim Verbinden — deshalb
   * merkt sich die Sitzung die Zuhörer und meldet sie bei jedem neuen
   * Transport erneut an. Sonst wäre die Stimme genau ab dem zweiten Raum
   * still, und man suchte den Fehler beim Mikrofon.
   */
  onPeerStream(listener: (stream: MediaStream, peerId: string) => void): void {
    this.streamListeners.push(listener);
    this.transport?.onPeerStream?.(listener);
  }

  setWorld(world: string): void {
    if (this.world !== world) this.worldSince = now();
    this.world = world;
    if (this.connected) {
      this.send({ type: 'world', from: this.localId, world, since: this.localSeniority });
    }
  }

  /** Sends the local pose at a fixed rate and expires stale peers. */
  update(dt: number, rig: PlayerRig, input: XRInput, now: number): void {
    if (!this.connected) return;

    this.poseTimer -= dt;
    if (this.poseTimer <= 0) {
      this.poseTimer = POSE_INTERVAL;
      rig.getHeadMatrix(_mat);
      // Kopf zuerst, Hände danach: `poseFromObject` schreibt selbst in `_mat`.
      const head = poseFromMatrix(_mat);
      const left = poseFromObject(input.get('left')?.grip ?? null);
      const right = poseFromObject(input.get('right')?.grip ?? null);
      this.send({
        type: 'pose',
        from: this.localId,
        pose: { head, left, right, hidden: !this.visible },
      });
    }

    for (const peer of [...this.peers.values()]) {
      if (now - peer.lastSeen > PEER_TIMEOUT) this.dropPeer(peer.id);
    }
  }

  private setStatus(status: NetStatus, detail: string): void {
    this.status = status;
    this.statusDetail = detail;
    for (const listener of this.statusListeners) listener(status, detail);
  }

  private send(message: NetMessage): void {
    this.transport?.send(message);
  }

  private receive(message: NetMessage): void {
    if (message.from === this.localId) return;
    const stamp = now();

    switch (message.type) {
      case 'hello': {
        const known = this.peers.has(message.from);
        const peer = this.touchPeer(message.from, stamp);
        peer.role = message.role;
        peer.name = message.name;
        // Fremder Text: Was niemand kennt, wird zur Vorgabe, statt einen
        // Körper zu bauen, den es nicht gibt.
        peer.look = clampAppearance({
          hat: message.hat as Appearance['hat'],
          head: message.head as Appearance['head'],
          body: message.body as Appearance['body'],
          figure: message.figure,
          face: message.face as Appearance['face'],
        });
        peer.world = message.world;
        setSeniority(peer, message.since);
        // Answer so the newcomer learns about us too — but only once, otherwise
        // two peers keep greeting each other forever.
        if (!known) this.announce();
        this.notifyChanged();
        break;
      }
      case 'world': {
        const peer = this.touchPeer(message.from, stamp);
        peer.world = message.world;
        setSeniority(peer, message.since);
        this.notifyChanged();
        break;
      }
      case 'pose': {
        this.touchPeer(message.from, stamp).pose = message.pose;
        break;
      }
      case 'chat': {
        const peer = this.touchPeer(message.from, stamp);
        // Der Name aus der Nachricht ist der aktuelle des Absenders; die
        // Peer-Liste kann eine `hello`-Runde hinterherhinken.
        if (typeof message.name === 'string' && message.name) peer.name = message.name;
        const incoming: ChatIn = {
          name: message.name,
          text: message.text,
          kind: message.kind === 'code' ? 'code' : 'text',
        };
        if (message.note) incoming.note = message.note;
        for (const listener of [...this.chatListeners]) listener(incoming, message.from);
        break;
      }
      case 'event': {
        this.touchPeer(message.from, stamp);
        for (const listener of this.channelListeners.get(message.channel) ?? []) {
          listener(message.data, message.from);
        }
        break;
      }
      case 'bye': {
        this.dropPeer(message.from);
        break;
      }
    }
  }

  private touchPeer(id: string, now: number): Peer {
    let peer = this.peers.get(id);
    if (!peer) {
      peer = {
        id,
        role: 'desktop',
        name: id,
        look: { ...DEFAULT_APPEARANCE },
        world: 'hub',
        pose: null,
        lastSeen: now,
        // Bis zur ersten Ansage gilt: gerade erst gekommen. Wer wirklich länger
        // da ist, sagt es im nächsten `hello`, und das kommt sofort.
        since: 0,
        sinceAt: performance.now() / 1000,
      };
      this.peers.set(id, peer);
      for (const listener of this.joinListeners) listener(peer);
      this.notifyChanged();
    }
    peer.lastSeen = now;
    return peer;
  }

  private notifyChanged(): void {
    for (const listener of this.changeListeners) listener();
  }

  private dropPeer(id: string): void {
    const peer = this.peers.get(id);
    if (!peer) return;
    this.peers.delete(id);
    for (const listener of this.leaveListeners) listener(peer);
    this.notifyChanged();
  }
}

/** Die eine Uhr dieser Datei: Sekunden, monoton, ohne Bezug zur Tageszeit. */
function now(): number {
  return performance.now() / 1000;
}

/** Trägt eine angesagte Standzeit ein — unbrauchbare Angaben zählen als „neu". */
function setSeniority(peer: Peer, since: unknown): void {
  peer.since = typeof since === 'number' && Number.isFinite(since) && since > 0 ? since : 0;
  peer.sinceAt = now();
}

function poseFromMatrix(matrix: THREE.Matrix4): PoseArray {
  matrix.decompose(_pos, _quat, _scale);
  return [
    round(_pos.x),
    round(_pos.y),
    round(_pos.z),
    round(_quat.x),
    round(_quat.y),
    round(_quat.z),
    round(_quat.w),
  ];
}

function poseFromObject(object: THREE.Object3D | null): PoseArray | null {
  if (!object || !object.visible) return null;
  object.updateMatrixWorld();
  return poseFromMatrix(_mat.copy(object.matrixWorld));
}

function round(value: number): number {
  return Math.round(value * 1000) / 1000;
}
